"""Dolly zoom from a real camera move. A push-in (or pull-back) is generated by the video model with true parallax; this
tracks the subject through it and re-frames every frame so the subject keeps one size and one place in the frame. What
is left is the vertigo: the camera got closer, but the zoom gave it all back, so only the background's perspective
changes (a push-in source: the world stretches away behind the subject; a pull-back: it looms forward).

Only crops are used (every frame is zoomed in by >= 1), so there is never an edge to invent. The frame the subject is
largest in is shown whole; the others are cropped in, at most `max_zoom`. If the move changes the subject's size more
than that, the lock is partial (the subject still grows or shrinks a little) rather than the picture going soft.

    A = track_subject(frames, masks)        # per-frame 3x3: frame-0 subject coordinates -> frame-t
    out, info = lock(frames, A, masks)      # re-framed frames, plus the zoom curve and how much of the move was locked
"""
import math

import cv2
import numpy as np


def _u8(f):
    return f if f.dtype == np.uint8 else (np.clip(f, 0, 1) * 255 + .5).astype(np.uint8)


def _centroid(m):
    ys, xs = np.nonzero(m > .5)
    return (float(xs.mean()), float(ys.mean())) if len(xs) > 30 else None


def track_subject(frames, masks=None, box=None, width=384):
    """Similarity transforms that carry the subject from frame 0 to each frame, from LK-tracked corners inside its mask
    (or, without a mask, inside `box` = (x0, y0, x1, y1) in pixels, default the middle of the frame, carried along by
    the track). Forward-backward checked and fitted with RANSAC, so background points that slip into the region are
    thrown out as long as the subject is most of it."""
    n, H, W = frames.shape[:3]
    sc = width / W
    w, h = width, max(2, int(round(H * sc)))
    g = [cv2.cvtColor(cv2.resize(_u8(f), (w, h), interpolation=cv2.INTER_AREA), cv2.COLOR_RGB2GRAY) for f in frames]
    if masks is not None:
        ms = [cv2.erode((cv2.resize(np.asarray(m, np.float32), (w, h)) > .5).astype(np.uint8) * 255, np.ones((5, 5), np.uint8)) for m in masks]
    else:
        x0, y0, x1, y1 = box if box is not None else (W * .3, H * .2, W * .7, H * .9)
        quad = np.float32([[x0, y0], [x1, y0], [x1, y1], [x0, y1]]) * sc
    S = np.diag([sc, sc, 1.0])
    Si = np.diag([1 / sc, 1 / sc, 1.0])
    A = [np.eye(3)]
    lk = dict(winSize=(21, 21), maxLevel=3, criteria=(cv2.TERM_CRITERIA_EPS | cv2.TERM_CRITERIA_COUNT, 30, .01))
    for t in range(n - 1):
        if masks is not None:
            region = ms[t]
            if region.sum() < 255 * 40 and t > 0:          # mask lost: keep the last region, carried by the last step
                region = ms[t - 1]
        else:
            q = cv2.perspectiveTransform(quad[None], S @ A[-1] @ Si)[0]
            region = np.zeros((h, w), np.uint8)
            cv2.fillConvexPoly(region, q.astype(np.int32), 255)
        p0 = cv2.goodFeaturesToTrack(g[t], 500, .005, 4, mask=region)
        step = None
        if p0 is not None and len(p0) >= 12:
            p1, s1, _ = cv2.calcOpticalFlowPyrLK(g[t], g[t + 1], p0, None, **lk)
            pb, s2, _ = cv2.calcOpticalFlowPyrLK(g[t + 1], g[t], p1, None, **lk)
            ok = (s1[:, 0] == 1) & (s2[:, 0] == 1) & (np.linalg.norm((pb - p0)[:, 0], axis=1) < .8)
            if ok.sum() >= 10:
                M, inl = cv2.estimateAffinePartial2D(p0[ok], p1[ok], method=cv2.RANSAC, ransacReprojThreshold=1.0, maxIters=3000, confidence=.995)
                if M is not None and inl is not None and inl.sum() >= 8:
                    step = Si @ np.vstack([M, [0, 0, 1]]) @ S
        if step is None and len(A) >= 2:                      # nothing to track: assume the last step's motion continues
            step = A[-1] @ np.linalg.inv(A[-2])
        A.append((step if step is not None else np.eye(3)) @ A[-1])
    return np.array(A)


def _smooth(x, sigma):
    if sigma <= 0 or len(x) < 3:
        return x
    r = int(3 * sigma)
    k = np.exp(-.5 * (np.arange(-r, r + 1) / sigma) ** 2)
    k /= k.sum()
    pad = np.pad(x, [(r, r)] + [(0, 0)] * (x.ndim - 1), mode="edge")
    return np.stack([np.convolve(pad[:, j], k, mode="valid") for j in range(x.shape[1])], 1) if x.ndim == 2 else np.convolve(pad, k, mode="valid")


def lock(frames, A, masks=None, max_zoom=1.6, strength=1.0, sigma=3.0, sharpen=.35):
    """Re-frame each frame so the tracked subject holds the size and place it has in the frame where it is largest."""
    n, H, W = frames.shape[:3]
    k = np.sqrt(np.abs(np.linalg.det(A[:, :2, :2])))
    logk = _smooth(np.log(np.maximum(k, 1e-6)), sigma)
    r = int(np.argmax(logk))                               # the reference: the subject at its largest, shown whole
    spread = float(logk.max() - logk.min())
    gamma = min(strength, math.log(max_zoom) / spread) if spread > 1e-6 else 0.0
    z = np.exp(gamma * (logk[r] - logk))                   # >= 1 everywhere: crops only
    # the anchor: the subject's centre in the reference frame, followed through the track
    c = _centroid(masks[r]) if masks is not None else None
    if c is None:
        c = tuple(np.float64([W / 2, H / 2]))
    Ar_inv = np.linalg.inv(A[r])
    P = np.array([(A[t] @ Ar_inv @ np.array([c[0], c[1], 1.0]))[:2] for t in range(n)])
    P = _smooth(P, sigma)
    Q = P[r]
    out = np.empty_like(frames)
    for t in range(n):
        cw, ch = W / z[t], H / z[t]
        ox = float(np.clip(P[t, 0] - Q[0] / z[t], 0, W - cw))
        oy = float(np.clip(P[t, 1] - Q[1] / z[t], 0, H - ch))
        M = np.float32([[z[t], 0, -ox * z[t]], [0, z[t], -oy * z[t]]])
        f = cv2.warpAffine(frames[t], M, (W, H), flags=cv2.INTER_LANCZOS4, borderMode=cv2.BORDER_REFLECT)
        if sharpen and z[t] > 1.02:                        # give back some of what the crop softened
            amt = sharpen * min((z[t] - 1) / (max_zoom - 1 + 1e-6), 1.0)
            f = cv2.addWeighted(f, 1 + amt, cv2.GaussianBlur(f, (0, 0), 1.2), -amt, 0)
        out[t] = np.clip(f, 0, 1) if out.dtype != np.uint8 else f
    info = dict(reference=r, zoom=z.tolist(), locked=round(gamma, 3), subject_scale=round(math.exp(spread), 3))
    return out, info
